import React, { useEffect, useState } from 'react';

export type VisualTreatmentType =
  | 'none'
  | 'gradient-text'
  | 'outline'
  | 'neon'
  | 'holographic'
  | 'glass'
  | 'stroke-gradient'
  | 'glitch'
  | '3d-block'
  | 'pattern-fill'
  | 'reflection';

export type TreatmentIntensity = 'low' | 'medium' | 'high';

interface VisualTreatmentProps {
  treatment: VisualTreatmentType;
  intensity?: TreatmentIntensity;
  pillarColor: string;
  children: React.ReactNode;
  target?: 'headline' | 'subtext' | 'bullets' | 'all';
}

export const VisualTreatment: React.FC<VisualTreatmentProps> = ({
  treatment,
  intensity = 'medium',
  pillarColor,
  children,
  target = 'all',
}) => {

  const treatments = {
    // Keep existing working treatments
    'gradient-text': {
      low: { background: `linear-gradient(135deg, ${pillarColor}, ${pillarColor}80)`, WebkitBackgroundClip: 'text', color: 'transparent' },
      medium: { background: `linear-gradient(135deg, ${pillarColor}, #fff)`, WebkitBackgroundClip: 'text', color: 'transparent' },
      high: { background: `linear-gradient(135deg, #fff, ${pillarColor}, #fff)`, WebkitBackgroundClip: 'text', color: 'transparent' },
    },
    outline: {
      low: { textShadow: `0 0 1px ${pillarColor}, 0 0 2px ${pillarColor}` },
      medium: { textShadow: `0 0 2px ${pillarColor}, 0 0 4px ${pillarColor}, 0 0 6px ${pillarColor}` },
      high: { textShadow: `0 0 3px ${pillarColor}, 0 0 6px ${pillarColor}, 0 0 9px ${pillarColor}, 0 0 12px ${pillarColor}` },
    },
    neon: {
      low: { textShadow: `0 0 5px ${pillarColor}, 0 0 10px ${pillarColor}` },
      medium: { textShadow: `0 0 10px ${pillarColor}, 0 0 20px ${pillarColor}, 0 0 30px ${pillarColor}` },
      high: { textShadow: `0 0 15px ${pillarColor}, 0 0 30px ${pillarColor}, 0 0 45px ${pillarColor}, 0 0 60px ${pillarColor}` },
    },

    // NEW TREATMENTS

    // Holographic - Iridescent rainbow effect
    holographic: {
      low: {
        background: `linear-gradient(135deg, ${pillarColor}aa, ${pillarColor}80, ${pillarColor}aa)`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
      },
      medium: {
        background: `linear-gradient(135deg, ${pillarColor}, #fff, ${pillarColor}, #fff, ${pillarColor})`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
      },
      high: {
        background: `conic-gradient(${pillarColor}, #ff00ff, #00ffff, #ff00ff, ${pillarColor})`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
        animation: 'holographicRotate 3s linear infinite',
      },
    },

    // Glass - Frosted glass effect
    glass: {
      low: {
        background: `linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0.05))`,
        backdropFilter: 'blur(5px)',
        WebkitBackdropFilter: 'blur(5px)',
        color: 'rgba(255,255,255,0.9)',
        border: '1px solid rgba(255,255,255,0.2)',
        padding: '4px 8px',
        borderRadius: '4px',
      },
      medium: {
        background: `linear-gradient(135deg, rgba(255,255,255,0.15), rgba(255,255,255,0.08))`,
        backdropFilter: 'blur(10px)',
        WebkitBackdropFilter: 'blur(10px)',
        color: 'rgba(255,255,255,0.95)',
        border: '2px solid rgba(255,255,255,0.3)',
        padding: '6px 12px',
        borderRadius: '6px',
      },
      high: {
        background: `linear-gradient(135deg, rgba(255,255,255,0.2), rgba(255,255,255,0.1))`,
        backdropFilter: 'blur(20px)',
        WebkitBackdropFilter: 'blur(20px)',
        color: 'rgba(255,255,255,1)',
        border: '3px solid rgba(255,255,255,0.4)',
        padding: '8px 16px',
        borderRadius: '8px',
        boxShadow: '0 0 20px rgba(255,255,255,0.2)',
      },
    },

    // Stroke Gradient - Gradient stroke with fill
    'stroke-gradient': {
      low: {
        WebkitTextStroke: '2px transparent',
        WebkitTextFillColor: pillarColor,
        background: `linear-gradient(135deg, #fff, ${pillarColor})`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        WebkitTextStrokeColor: 'transparent',
      },
      medium: {
        WebkitTextStroke: '4px transparent',
        WebkitTextFillColor: pillarColor,
        background: `linear-gradient(135deg, #fff, ${pillarColor}, #fff)`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        WebkitTextStrokeColor: 'transparent',
      },
      high: {
        WebkitTextStroke: '6px transparent',
        WebkitTextFillColor: pillarColor,
        background: `conic-gradient(${pillarColor}, #fff, ${pillarColor})`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        WebkitTextStrokeColor: 'transparent',
        filter: 'drop-shadow(0 0 10px rgba(0,0,0,0.3))',
      },
    },

    // Glitch - Offset layers with chromatic aberration
    glitch: {
      low: {
        position: 'relative',
      },
      medium: {
        position: 'relative',
      },
      high: {
        position: 'relative',
        animation: 'glitch 0.3s infinite',
      },
    },

    // 3D Block - Stacked layers for 3D extrusion
    '3d-block': {
      low: {
        position: 'relative',
      },
      medium: {
        position: 'relative',
      },
      high: {
        position: 'relative',
      },
    },

    // Pattern Fill - Pattern backgrounds clipped to text
    'pattern-fill': {
      low: {
        background: `radial-gradient(circle, ${pillarColor} 2px, transparent 2px)`,
        backgroundSize: '20px 20px',
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
      },
      medium: {
        background: `linear-gradient(${pillarColor} 2px, transparent 2px), linear-gradient(90deg, ${pillarColor} 2px, transparent 2px)`,
        backgroundSize: '15px 15px',
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
      },
      high: {
        background: `repeating-linear-gradient(45deg, ${pillarColor}, ${pillarColor} 2px, transparent 2px, transparent 10px)`,
        WebkitBackgroundClip: 'text',
        backgroundClip: 'text',
        color: 'transparent',
        mixBlendMode: 'screen',
      },
    },

    // Reflection - Mirror effect below text
    reflection: {
      low: {
        WebkitBoxReflect: 'below 0px linear-gradient(transparent, rgba(255,255,255,0.2))',
      },
      medium: {
        WebkitBoxReflect: 'below 10px linear-gradient(transparent, rgba(255,255,255,0.4))',
      },
      high: {
        WebkitBoxReflect: 'below 20px linear-gradient(transparent 50%, rgba(255,255,255,0.6))',
        filter: 'blur(1px)',
      },
    },

    none: {},
  };

  // Early return for 'none' treatment
  if (treatment === 'none' || !treatment) {
    return <>{children}</>;
  }

  const treatmentStyles = treatments[treatment as keyof typeof treatments];

  // Check if treatment exists and has intensity
  if (!treatmentStyles || !intensity) {
    return <>{children}</>;
  }

  const intensityStyles = (treatmentStyles as any)[intensity];

  // Check if intensity styles exist
  if (!intensityStyles) {
    return <>{children}</>;
  }

  const isGradientText = treatment === 'gradient-text' || treatment === 'holographic';
  const isPatternFill = treatment === 'pattern-fill';
  const isGlass = treatment === 'glass';
  const isStrokeGradient = treatment === 'stroke-gradient';
  const isGlitch = treatment === 'glitch';
  const is3DBlock = treatment === '3d-block';
  const isReflection = treatment === 'reflection';

  // Get text content for special treatments
  const textContent = React.Children.toArray(children).join('');

  // Glitch effect - multiple layers with offset
  if (isGlitch) {
    const offset = intensity === 'high' ? 6 : intensity === 'medium' ? 4 : 2;
    const glitchY = Math.random() * 100;
    const glitchY2 = Math.random() * 100;

    return (
      <div style={{ position: 'relative', display: 'inline-block' }}>
        {/* Main layer */}
        <span style={{ position: 'relative', color: pillarColor }}>{children}</span>
        {/* Cyan layer */}
        <span
          style={{
            position: 'absolute',
            left: `${offset}px`,
            top: '0',
            color: '#0ff',
            clipPath: `polygon(0 ${glitchY}%, 100% ${glitchY}%, 100% ${glitchY + 10}%, 0 ${glitchY + 10}%)`,
            opacity: 0.8,
          }}
        >
          {children}
        </span>
        {/* Magenta layer */}
        <span
          style={{
            position: 'absolute',
            left: `-${offset}px`,
            top: '0',
            color: '#f0f',
            clipPath: `polygon(0 ${glitchY2}%, 100% ${glitchY2}%, 100% ${glitchY2 + 10}%, 0 ${glitchY2 + 10}%)`,
            opacity: 0.8,
          }}
        >
          {children}
        </span>
      </div>
    );
  }

  // 3D Block effect - stacked layers
  if (is3DBlock) {
    const layerCount = intensity === 'high' ? 10 : intensity === 'medium' ? 6 : 3;
    const offset = intensity === 'high' ? 2 : 1;

    const layers = Array.from({ length: layerCount }).map((_, i) => (
      <span
        key={i}
        style={{
          position: 'absolute',
          left: `${i * offset}px`,
          top: `${i * offset}px`,
          color: pillarColor,
          opacity: 1 - (i / layerCount) * 0.5,
          zIndex: layerCount - i,
          pointerEvents: 'none',
        }}
      >
        {children}
      </span>
    ));

    return (
      <div style={{ position: 'relative', display: 'inline-block' }}>
        {layers}
        <span style={{ position: 'relative', color: '#fff', zIndex: layerCount + 1 }}>{children}</span>
      </div>
    );
  }

  // Stroke Gradient - needs special handling for WebkitTextStroke
  if (isStrokeGradient) {
    const strokeWidth = intensity === 'high' ? 6 : intensity === 'medium' ? 4 : 2;
    const gradient = intensity === 'high'
      ? `conic-gradient(${pillarColor}, #fff, ${pillarColor})`
      : intensity === 'medium'
      ? `linear-gradient(135deg, #fff, ${pillarColor}, #fff)`
      : `linear-gradient(135deg, #fff, ${pillarColor})`;

    return (
      <div
        style={{
          ...intensityStyles,
          WebkitTextStroke: `${strokeWidth}px transparent`,
          WebkitTextFillColor: pillarColor,
          background: gradient,
          WebkitBackgroundClip: 'text',
          backgroundClip: 'text',
          display: 'inline-block',
        }}
      >
        {children}
      </div>
    );
  }

  return (
    <div
      style={{
        ...intensityStyles,
        WebkitTextFillColor: isGradientText || isPatternFill ? 'transparent' : undefined,
        display: 'inline-block',
      }}
    >
      {children}
    </div>
  );
};

// Add keyframes for animations (client-side only)
if (typeof document !== 'undefined') {
  const style = document.createElement('style');
  style.textContent = `
    @keyframes holographicRotate {
      0% { filter: hue-rotate(0deg); }
      100% { filter: hue-rotate(360deg); }
    }

    @keyframes glitch {
      0% { transform: translate(0); }
      20% { transform: translate(-2px, 2px); }
      40% { transform: translate(-2px, -2px); }
      60% { transform: translate(2px, 2px); }
      80% { transform: translate(2px, -2px); }
      100% { transform: translate(0); }
    }
  `;
  document.head.appendChild(style);
}